def check_name(s):
    if NAME_RE.match(s) is not None:
        return
    if len(s) > 64:
        raise LimitErr()
    raise SchemaErr()


# --------------------------------------------------------------------------
# request dispatch and validation
# --------------------------------------------------------------------------

def handle(obj):
    if type(obj) is not dict:
        raise SchemaErr()
    op = obj.get('op')
    if type(op) is not str:
        raise SchemaErr()
    if op == 'replay':
        if frozenset(obj) != REPLAY_KEYS:
            raise SchemaErr()
    elif op == 'audit' or op == 'export':
        if frozenset(obj) != GRAPH_KEYS:
            raise SchemaErr()
    else:
        raise SchemaErr()
    P, R, D, inp = validate_inputs(obj['inputs'])
    if op == 'replay':
        return do_replay(obj, P, R, D, inp)
    return do_graph(obj, op, P, R, D, inp)


def validate_inputs(v):
    """Validate the P x R x D rank-major rectangular integer array."""
    if type(v) is not list:
        raise SchemaErr()
    P = len(v)
    if P < 1 or P > 8:
        raise LimitErr()
    for row in v:
        if type(row) is not list:
            raise SchemaErr()
    R = len(v[0])
    if R > 128:
        raise LimitErr()
    for row in v:
        if len(row) != R:
            raise SchemaErr()
    if R == 0:
        return P, 0, 0, v
    first = v[0][0]
    if type(first) is not list:
        raise SchemaErr()
    D = len(first)
    if D > 32:
        raise LimitErr()
    for row in v:
        for vec in row:
            if type(vec) is not list:
                raise SchemaErr()
            w = len(vec)
            if w != D:
                if w > 32:
                    raise LimitErr()
                raise SchemaErr()
            for x in vec:
                if type(x) is not int:
                    raise SchemaErr()
                if x < -NINE or x > NINE:
                    raise LimitErr()
    return P, R, D, v


# --------------------------------------------------------------------------
# replay
# --------------------------------------------------------------------------

def do_replay(obj, P, R, D, inp):
    slots_n = obj['slots']
    if type(slots_n) is not int:
        raise SchemaErr()
    if slots_n < 1 or slots_n > 16:
        raise LimitErr()
    window = obj['window']
    if type(window) is not int:
        raise SchemaErr()
    if window < 1 or window > slots_n:
        raise LimitErr()
    raw_ev = obj['events']
    if type(raw_ev) is not list:
        raise SchemaErr()
    if len(raw_ev) > 20000:
        raise LimitErr()
    events = []
    for e in raw_ev:
        if type(e) is not list:
            raise SchemaErr()
        ne = len(e)
        if ne == 0:
            raise SchemaErr()
        k = e[0]
        if k == 'send':
            if ne != 3:
                raise SchemaErr()
            r = e[1]
            q = e[2]
            if type(r) is not int or type(q) is not int:
                raise SchemaErr()
            if r < 0 or r >= P:
                raise LimitErr()
            if q < 0 or q >= R:
                raise LimitErr()
            events.append((0, r, q))
        elif k == 'retry':
            if ne != 2:
                raise SchemaErr()
            r = e[1]
            if type(r) is not int:
                raise SchemaErr()
            if r < 0 or r >= P:
                raise LimitErr()
            events.append((1, r, 0))
        elif k == 'deliver' or k == 'drop' or k == 'duplicate':
            if ne != 2:
                raise SchemaErr()
            pid = e[1]
            if type(pid) is not int:
                raise SchemaErr()
            if pid < 0 or pid > 200000:
                raise LimitErr()
            if k == 'deliver':
                events.append((2, pid, 0))
            elif k == 'drop':
                events.append((3, pid, 0))
            else:
                events.append((4, pid, 0))
        else:
            raise SchemaErr()
    return run_replay(P, R, D, inp, slots_n, window, events)
